// Public ATS boards — Saudi Arabia + global remote-friendly companies
const greenhouse = ["neom", "careem", "hungerstation", "tamara", "stripe", "gitlab", "cloudflare", "anthropic", "linear", "figma", "vercel"];
const lever = ["noon", "canva"];
const ashby = ["openai", "ramp", "deel"];
const out = [];
for (const s of greenhouse) {
  out.push({ json: { board: "greenhouse", company: s, url: "https://boards-api.greenhouse.io/v1/boards/" + s + "/jobs?content=true" } });
}
for (const s of lever) {
  out.push({ json: { board: "lever", company: s, url: "https://api.lever.co/v0/postings/" + s + "?mode=json" } });
}
for (const s of ashby) {
  out.push({ json: { board: "ashby", company: s, url: "https://api.ashbyhq.com/posting-api/job-board/" + s } });
}
return out;

const sources = $("Build Public Board Sources").all();
const responses = $input.all();
const out = [];

function strip(html) {
  if (!html) return "";
  return String(html)
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/\s+/g, " ")
    .trim();
}

for (let i = 0; i < responses.length; i++) {
  const src = (sources[i] && sources[i].json) || {};
  const body = responses[i].json || {};
  const board = src.board;
  const company = src.company || "";
  let list = [];

  if (board === "greenhouse") list = Array.isArray(body.jobs) ? body.jobs : [];
  else if (board === "lever") list = Array.isArray(body) ? body : [];
  else if (board === "ashby") list = Array.isArray(body.jobs) ? body.jobs : [];

  for (const j of list) {
    let title = "", loc = "", url = "", desc = "", ext = "", datePosted = null;

    if (board === "greenhouse") {
      title = j.title || "";
      loc = (j.location && j.location.name) || "";
      url = j.absolute_url || "";
      desc = strip(j.content);
      ext = "greenhouse-" + company + "-" + j.id;
      datePosted = j.updated_at || j.first_published || null;
    } else if (board === "lever") {
      title = j.text || "";
      loc = (j.categories && j.categories.location) || "";
      url = j.hostedUrl || "";
      desc = strip(j.descriptionPlain || j.description);
      ext = "lever-" + company + "-" + j.id;
      datePosted = j.createdAt || null;
    } else if (board === "ashby") {
      title = j.title || "";
      loc = j.location || "";
      url = j.jobUrl || j.applyUrl || "";
      desc = strip(j.descriptionPlain || j.description);
      ext = "ashby-" + company + "-" + (j.id || j.jobId);
      datePosted = j.publishedAt || null;
    }

    out.push({
      json: {
        external_id: ext,
        company,
        job_title: title,
        job_location: loc,
        job_url: url,
        source: board,
        description: (desc || "").slice(0, 6000),
        date_posted: datePosted
      }
    });
  }
}

return out;

// Adzuna Saudi Arabia (country code: sa) + multiple title searches
const queries = [
  "software engineer",
  "AI engineer",
  "machine learning engineer",
  "backend engineer",
  "full stack engineer",
  "python developer",
  "LLM engineer",
  "prompt engineer",
  "mobile developer",
  "ios developer"
];
const out = [];
for (const what of queries) {
  out.push({ json: {
    board: "adzuna",
    query: what,
    url: "https://api.adzuna.com/v1/api/jobs/sa/search/1?results_per_page=50&what=" + encodeURIComponent(what) + "&content-type=application/json"
  }});
}
return out;

const out = [];

for (const item of $input.all()) {
  const body = item.json || {};
  const list = Array.isArray(body.results) ? body.results : [];

  for (const j of list) {
    out.push({
      json: {
        external_id: "adzuna-" + j.id,
        company: (j.company && j.company.display_name) || "",
        job_title: j.title || "",
        job_location: (j.location && j.location.display_name) || "",
        job_url: j.redirect_url || "",
        source: "adzuna",
        description: String(j.description || "").slice(0, 6000),
        date_posted: j.created || null
      }
    });
  }
}

return out;

const profile = $("Get Profile").first().json || {};
const existingRows = $("Get Existing Applications").all();
const existingIds = new Set(existingRows.map(r => (r.json && r.json.external_id)).filter(Boolean));

const titleGroups = [
  ["software engineer", "software developer"],
  ["ai engineer", "artificial intelligence engineer", "ai automation engineer"],
  ["machine learning", "ml engineer"],
  ["backend engineer", "back end engineer", "back-end engineer"],
  ["full stack", "fullstack"],
  ["mobile developer", "ios developer", "ios engineer"],
  ["python developer"],
  ["llm engineer", "prompt engineer"]
];

// Block senior / management roles (IC only)
const seniorBlock = [
  "senior", "staff", "principal", "lead", "manager", "director",
  "head of", "vp ", "vice president", "chief", "distinguished", "architect"
];

const saudiCities = [
  "riyadh", "jeddah", "dammam", "khobar", "al khobar", "dhahran",
  "makkah", "madinah", "neom", "tabuk", "saudi", "ksa"
];
const remoteTerms = ["remote", "work from home", "wfh", "anywhere", "distributed"];
const hybridTerms = ["hybrid"];
const onsiteTerms = ["on-site", "onsite", "on site", "office-based"];

const profileLocs = String(profile.target_locations || "Remote,Riyadh,Jeddah,Dammam,Khobar")
  .toLowerCase()
  .split(",")
  .map(s => s.trim())
  .filter(Boolean);

const includeRemote = profile.include_remote !== false;
const includeHybrid = profile.include_hybrid !== false;
const includeOnsite = profile.include_onsite !== false;

const maxAgeDays = Number(profile.max_job_age_days || 7);
const maxJobsPerRun = Number(profile.max_jobs_per_run || 30);

const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - maxAgeDays);
cutoff.setHours(0, 0, 0, 0);

function parseDate(value) {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d;
}

function detectWorkType(locationText, descriptionText) {
  const text = `${locationText} ${descriptionText}`.toLowerCase();
  if (remoteTerms.some(k => text.includes(k))) return "remote";
  if (hybridTerms.some(k => text.includes(k))) return "hybrid";
  if (onsiteTerms.some(k => text.includes(k))) return "onsite";
  return "unknown";
}

const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.external_id || !j.job_title) continue;

  const title = String(j.job_title).toLowerCase();
  const loc = String(j.job_location || "").toLowerCase();
  const desc = String(j.description || "").toLowerCase();
  const fullBlob = `${title} ${loc} ${desc}`;

  // IC titles only — drop Manager / Senior / Staff etc.
  if (seniorBlock.some(k => title.includes(k))) continue;

  const titleMatch = titleGroups.some(g => g.some(k => title.includes(k)));
  if (!titleMatch) continue;

  const posted = parseDate(j.date_posted || j.created_at || j.updated_at);
  if (posted && posted < cutoff) continue;

  const saudiMatch = saudiCities.some(c => fullBlob.includes(c));
  const remoteMatch = includeRemote && remoteTerms.some(t => fullBlob.includes(t));
  const profileLocMatch = profileLocs.some(t => fullBlob.includes(t));

  // Block obvious onsite-only locations outside Saudi unless explicitly remote
  const blockedOnsiteHints = [
    "israel", "tel aviv", "dublin", "berlin", "paris", "toronto",
    "singapore", "sydney", "munich", "amsterdam", "london, uk", "new york"
  ];
  const blockedOnsite = blockedOnsiteHints.some(h => fullBlob.includes(h));
  if (blockedOnsite && !remoteMatch) continue;

  if (!saudiMatch && !remoteMatch && !profileLocMatch) continue;

  const workType = detectWorkType(loc, desc);
  if (workType === "remote" && !includeRemote) continue;
  if (workType === "hybrid" && !includeHybrid) continue;
  if (workType === "onsite" && !includeOnsite) continue;

  if (existingIds.has(j.external_id)) continue;

  out.push({ json: { ...j, work_type: workType, date_posted: posted ? posted.toISOString() : null } });
}

return out.slice(0, maxJobsPerRun);

const LF = String.fromCharCode(10);
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0 && r.external_id);
const prepared = rows.filter(r => r.status === "prepared");
const lowScore = rows.filter(r => r.status === "skipped_low_score");
const errors = rows.filter(r => r.status === "error");
const profile = $("Get Profile").first().json || {};
const appUrl = String(profile.site_url || "http://localhost:3000").replace(/\/$/, "");

const esc = (s) => String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const html = [
  "<div style=\"font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-width:560px;margin:0 auto;padding:24px\">",
  "<h2 style=\"margin:0 0 8px\">JobPilot — تحديث جديد على الموقع</h2>",
  "<p style=\"color:#555;margin:0 0 16px\">Run: " + esc($execution.id) + "</p>",
  prepared.length
    ? "<p style=\"font-size:16px;line-height:1.6\">عندك <strong>" + prepared.length + "</strong> وظيفة جاهزة للمراجعة. السيرة والكفر لتر PDF موجودين في الموقع.</p>"
    : "<p style=\"font-size:16px;line-height:1.6\">ما في وظائف جديدة جاهزة اليوم. راجع الموقع للتفاصيل.</p>",
  "<p style=\"margin:20px 0\"><a href=\"" + esc(appUrl + "/applications") + "\" style=\"display:inline-block;background:#2563eb;color:#fff;text-decoration:none;padding:12px 18px;border-radius:10px;font-weight:600\">افتح Applications في JobPilot</a></p>",
  "<ul style=\"color:#444;line-height:1.8;padding-left:18px\">",
  "<li>Matching new jobs processed: " + rows.length + "</li>",
  "<li>Prepared (PDF ready on site): " + prepared.length + "</li>",
  "<li>Skipped (below threshold): " + lowScore.length + "</li>",
  "<li>Errors: " + errors.length + "</li>",
  "</ul>",
  "<p style=\"color:#888;font-size:12px;margin-top:20px\">التفاصيل الكاملة والملفات على الموقع — الإيميل للتنبيه فقط.</p>",
  "</div>"
].join(LF);

const subject = prepared.length
  ? "JobPilot: " + prepared.length + " وظيفة جديدة جاهزة — شيك الموقع"
  : "JobPilot: تحديث يومي — " + rows.length + " وظيفة تم فحصها";

return [{ json: { subject, html, prepared: prepared.length, processed: rows.length, appUrl } }];

// Deterministic match score — NO AI. Compares job vs resume_text only.
const profile = $("Get Profile").first().json || {};
const job = $input.item.json || {};

const resumeText = String(profile.resume_text || "").toLowerCase();
const jobTitle = String(job.job_title || "").toLowerCase();
const jobDesc = String(job.description || "").toLowerCase();
const jobLoc = String(job.job_location || "").toLowerCase();
const blob = `${jobTitle} ${jobDesc} ${jobLoc}`;

const titleGroups = [
  ["software engineer", "software developer"],
  ["ai engineer", "artificial intelligence engineer", "ai automation engineer"],
  ["machine learning", "ml engineer"],
  ["backend engineer", "back end engineer", "back-end engineer"],
  ["full stack", "fullstack"],
  ["mobile developer", "ios developer", "ios engineer"],
  ["python developer"],
  ["llm engineer", "prompt engineer"]
];

const saudiCities = [
  "riyadh", "jeddah", "dammam", "khobar", "al khobar", "dhahran",
  "makkah", "madinah", "neom", "tabuk", "saudi", "ksa"
];
const remoteTerms = ["remote", "work from home", "wfh", "anywhere", "distributed"];

// Skills explicitly listed in profile (comma string or array)
let profileSkills = [];
if (Array.isArray(profile.skills)) {
  profileSkills = profile.skills.map((s) => String(s).toLowerCase().trim()).filter(Boolean);
} else if (typeof profile.skills === "string") {
  profileSkills = profile.skills.split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
}

// Extra tokens only if they appear in resume_text (never invent)
const TECH_HINTS = [
  "python", "javascript", "typescript", "java", "react", "node.js", "node",
  "aws", "docker", "kubernetes", "sql", "postgresql", "mongodb", "redis",
  "fastapi", "django", "flask", "llm", "gpt", "openai", "machine learning",
  "deep learning", "tensorflow", "pytorch", "swift", "kotlin", "go", "golang",
  "rust", "api", "microservices", "git", "ci/cd", "azure", "gcp", "linux",
  "next.js", "vue", "angular", "graphql", "kafka", "spark", "nlp", "rag"
];

const candidateTerms = new Set([...profileSkills]);
for (const hint of TECH_HINTS) {
  if (resumeText.includes(hint)) candidateTerms.add(hint);
}

const matched_skills = [];
const missing_skills = [];

for (const term of candidateTerms) {
  if (term.length < 2) continue;
  if (blob.includes(term)) matched_skills.push(term);
}

for (const hint of TECH_HINTS) {
  if (blob.includes(hint) && !resumeText.includes(hint) && !missing_skills.includes(hint)) {
    missing_skills.push(hint);
  }
}

// ── Title fit (0–25) ──
let titleScore = 0;
if (titleGroups.some((g) => g.some((k) => jobTitle.includes(k)))) titleScore = 18;

const profileTitles = String(profile.target_titles || profile.job_titles || "")
  .toLowerCase()
  .split(",")
  .map((s) => s.trim())
  .filter(Boolean);
if (profileTitles.some((t) => jobTitle.includes(t))) titleScore = 25;

// ── Skills overlap (0–40) ──
const skillScore = Math.min(40, matched_skills.length * 6);

// ── Experience / keyword density (0–20) ──
const expScore = Math.min(20, matched_skills.length * 2);

// ── Location fit (0–15) ──
let locScore = 5;
if (saudiCities.some((c) => blob.includes(c))) locScore = 15;
else if (remoteTerms.some((t) => blob.includes(t))) locScore = 12;
else if (!jobLoc.trim()) locScore = 8;

let match_score = Math.min(100, Math.round(titleScore + skillScore + expScore + locScore));

// Penalty if job asks for many skills not in resume
if (missing_skills.length >= 6) match_score = Math.max(0, match_score - 12);
else if (missing_skills.length >= 3) match_score = Math.max(0, match_score - 5);

const summary = [
  `Code match ${match_score}/100.`,
  `Title ${titleScore}/25, skills ${skillScore}/40, experience ${expScore}/20, location ${locScore}/15.`,
  matched_skills.length
    ? `Matched: ${matched_skills.slice(0, 10).join(", ")}.`
    : "No strong skill overlap found.",
  missing_skills.length
    ? `Missing from resume: ${missing_skills.slice(0, 6).join(", ")}.`
    : ""
].filter(Boolean).join(" ");

return {
  json: {
    ...job,
    output: {
      match_score,
      matched_skills,
      missing_skills: missing_skills.slice(0, 15),
      required_keywords: missing_skills.slice(0, 10),
      summary,
      scorer: "code"
    }
  }
};

