const p = $("Get Profile").first().json || {};
const job = $("Loop Over Jobs").item.json || {};
const ai = $("Code Match Score").item.json.output || {};
const fields = {
  name: p.full_name || "", email: p.email || "", phone: p.phone || "",
  linkedin: p.linkedin || "", github: p.github || "", portfolio: p.portfolio || ""
};
const notes = JSON.stringify({
  application_fields: fields,
  matched_skills: ai.matched_skills || [],
  missing_skills: ai.missing_skills || [],
  required_keywords: ai.required_keywords || [],
  ai_summary: ai.summary || ""
});
return { json: { notes: notes } };

const profile = $("Get Profile").first().json || {};
const job = $("Loop Over Jobs").item.json || {};
const kit = $("Build Application Kit").item.json || {};

return {
  json: {
    siteUrl: String(profile.site_url || "http://localhost:3000").replace(/\/$/, ""),
    secret: profile.ingest_secret || "",
    payload: {
      external_id: job.external_id,
      company: job.company,
      job_title: job.job_title,
      job_location: job.job_location || "",
      job_url: job.job_url || "",
      source: job.source || "",
      match_score: $("Code Match Score").item.json.output.match_score,
      resume_version: `tailored-${$now.toFormat("yyyyLLdd")}`,
      tailored_resume: $("Tailor Resume").item.json.text,
      cover_letter: $("Write Cover Letter").item.json.text,
      date_found: $now.toISO(),
      run_id: $execution.id,
      notes: kit.notes || ""
    }
  }
};

const push = $("Push to JobPilot").item.json || {};
const kit = $("Build Application Kit").item.json || {};

let notes = {};
try {
  notes = JSON.parse(kit.notes || "{}");
} catch {
  notes = { raw: kit.notes || "" };
}

notes.site = {
  ok: push.ok === true,
  viewUrl: push.viewUrl || "",
  resumePdfUrl: push.resumePdfUrl || "",
  coverLetterPdfUrl: push.coverLetterPdfUrl || "",
  id: push.id || ""
};

if (push.error || push.message) {
  notes.site.error = push.error || push.message;
}

return {
  json: {
    notes: JSON.stringify(notes)
  }
};
